INSERT IGNORE INTO `la_app` (`code`,`name`,`icon`,`description`,`category`,`cover`,`client_tags`,`is_builtin`,`sort`,`current_version`,`status`,`expire_policy`,`install_time`,`update_time`) VALUES ('aigc_product_video','商品视频','resource/image/common/menu_generator.png','基于商品素材创作视频，支持商品信息识别、视频描述生成与商品视频创作。','aigc','','platform,tenant,pc,uniapp',1,846,'1.0.0','installed','allow',UNIX_TIMESTAMP(),UNIX_TIMESTAMP());
INSERT IGNORE INTO `la_app_version` (`app_code`,`version`,`require_core`,`package_path`,`manifest_json`,`changelog`,`status`,`create_time`) VALUES ('aigc_product_video','1.0.0','>=1.0.0','local','{"code":"aigc_product_video","name":"商品视频","version":"1.0.0","require_core":">=1.0.0","description":"基于商品素材创作视频，支持商品信息识别、视频描述生成与商品视频创作。","changelog":"1. 普通模式直接描述，高级模式智能分析商品素材。\\n2. 智能分析完成后自动回填商品信息和视频描述，可修改后生成视频。\\n3. 移除分镜图片生成和相关模型配置。\\n4. 创作记录仅展示视频生成，保留完整配置并支持设为灵感模板。\\n5. 灵感模板一键同款回填完整配置，创建独立草稿。\\n6. 灵感模板只复用素材与创作设置，同款草稿不携带商品来源链接。\\n7. 平台可将灵感模板设为内置，所有启用应用的租户可使用完整配置，图片和视频共用对象存储素材。\\n8. 支持后台手动新增灵感模板，以及视频创作记录的筛选、预览和删除。","icon":"resource/image/common/menu_generator.png","category":"aigc","cover":"","is_builtin":1,"expire_policy":"allow","sort":846,"frontends":["platform","tenant","pc","uniapp"],"api_prefix":"/app/aigc_product_video","menus":"menus/tenant.json","permissions":"permissions/tenant.json","migrations":"migrations","dependencies":[{"app_code":"aigc_video","name":"视频创作","required_for":"生成商品视频"}],"billing":{"provider":"power_market","actions":["product","reference","plan","analysis","write","optimize","video","chapters"],"currency":"points"},"frontend_entries":[{"terminal":"pc","entry_key":"aigc_product_video","name":"商品视频","path":"/ai/tools/aigc_product_video","icon":"resource/image/common/menu_generator.png","sort":84,"status":1},{"terminal":"tenant","entry_key":"aigc_product_video_admin","name":"商品视频","path":"/apps/aigc_product_video/config","icon":"el-icon-VideoCamera","sort":84,"status":1},{"terminal":"uniapp","entry_key":"aigc_product_video","name":"商品视频","path":"/apps/aigc_product_video/pages/creator/index","icon":"resource/image/common/menu_generator.png","sort":846,"status":1,"meta":{"pages":[{"name":"创作首页","path":"/apps/aigc_product_video/pages/creator/index"},{"name":"历史创作","path":"/apps/aigc_product_video/pages/tasks/index"}]}}]}','1. 普通模式直接描述，高级模式智能分析商品素材。
